def height_range_str(race):
    lo,hi = RACE_HEIGHTS.get(race, (56,74))
    return f'{lo//12}\'{lo%12}" – {hi//12}\'{hi%12}"'

def random_height(race):
    lo,hi = RACE_HEIGHTS.get(race, (56,74))
    inches = random.randint(lo,hi)
    return f"{inches//12}'{inches%12}\""

