# Build complete race dict
DND_RACES = {}
for name, data in {**_base, **_animal, **_scifi}.items():
    h = RACE_HEIGHTS.get(name, (56,74))
    data["height"] = f'{h[0]//12}\'{h[0]%12}" – {h[1]//12}\'{h[1]%12}"'
    DND_RACES[name] = data
DND_RACES["Custom Race"] = {"traits":["Custom"],"features":["Custom"],"lore":"Your own creation.","stat_bonuses":{},"speed":30,"size":"Medium","languages":["Common"],"weight":"Varies","age_range":"Varies","height":"Varies","skin":["Custom"],"hair":["Custom"],"eyes":["Custom"]}

# ══════ MEASUREMENTS ══════
RACE_MEASUREMENTS = {r: {"m":{"bust":(34,46),"waist":(28,38),"hip":(32,40)},"f":{"bust":(30,42),"waist":(24,34),"hip":(32,44)},"n":{"bust":(30,44),"waist":(24,36),"hip":(30,42)}} for r in DND_RACES}
# Overrides for specific races
for r in ["Gnome","Halfling","Ferengi"]: RACE_MEASUREMENTS[r]={"m":{"bust":(22,32),"waist":(18,26),"hip":(22,30)},"f":{"bust":(20,30),"waist":(16,24),"hip":(22,32)},"n":{"bust":(20,30),"waist":(16,26),"hip":(20,30)}}
for r in ["Goliath","Bear Person","Firbolg"]: RACE_MEASUREMENTS[r]={"m":{"bust":(44,56),"waist":(34,46),"hip":(38,48)},"f":{"bust":(38,50),"waist":(30,40),"hip":(38,50)},"n":{"bust":(40,54),"waist":(32,44),"hip":(38,48)}}
for r in ["Dragonborn","Half-Orc","Klingon","Jaffa","Narn","Shark Person","Tiger Person","Lion Person"]: RACE_MEASUREMENTS[r]={"m":{"bust":(38,52),"waist":(30,42),"hip":(34,44)},"f":{"bust":(34,46),"waist":(26,36),"hip":(34,46)},"n":{"bust":(36,48),"waist":(28,40),"hip":(34,46)}}
for r in ["Cat Person (Neko)","Rabbit Person (Usagi)","Bird Person (Harpy)","Deer Person"]: RACE_MEASUREMENTS[r]={"m":{"bust":(30,40),"waist":(24,32),"hip":(28,36)},"f":{"bust":(28,38),"waist":(22,28),"hip":(30,40)},"n":{"bust":(28,38),"waist":(22,30),"hip":(28,38)}}
_DEF={"m":{"bust":(34,46),"waist":(28,38),"hip":(32,42)},"f":{"bust":(30,42),"waist":(24,34),"hip":(32,44)},"n":{"bust":(30,44),"waist":(24,36),"hip":(30,42)}}

def get_measurement_range(race,gender):
    rm=RACE_MEASUREMENTS.get(race,_DEF); g=(gender or "").lower()
    cat="f" if g in("female","f","futa / futanari","futa") else("m" if g in("male","m") else "n")
    d=rm.get(cat,rm.get("n",_DEF["n"])); return d["bust"],d["waist"],d["hip"]

def random_measurements(race,gender):
    b,w,h=get_measurement_range(race,gender)
    return f'{random.randint(*b)}"',f'{random.randint(*w)}"',f'{random.randint(*h)}"'

# ═══ RANDOM BACKSTORY / SCENARIO / GOALS GENERATORS ═══
_BACKSTORIES = [
    """Orphaned at three, left on the monastery steps in a snowstorm with nothing but a wool blanket and a coin no one could identify. The {race} monks raised them in silence — literally, since novices spoke only one hour a day, the rest given to sword forms, meditation, and copying scripture until their hands cramped. They loved it there, the smell of incense and cold stone, the certainty of the bell schedule. Then came the night raiders scaled the eastern wall. They hid in the grain cellar as instructed and stayed hidden — the training held, even as the screaming didn't stop and then did. They were the only one to walk out the gate the next morning. A tattoo they don't remember receiving appeared on their shoulder blade that same night, in a script none of the surviving texts can translate. They carry the monastery's last surviving prayer book and have never opened it past the first page. Someday they will. Not yet.""",

    """Grew up picking pockets in the tannery district, where the smell alone kept the city guard from patrolling too closely. They were good — fast hands, faster excuses — until the day they lifted a coin purse from a {profession} who turned around before they'd taken three steps and simply said, "Buy me a drink with that, and I'll teach you to do it properly." What followed was five years of apprenticeship disguised as friendship: real skills, real discipline, the first steady meals of their life. Then the mentor vanished on a routine errand, leaving behind a locked strongbox, a journal written in a cipher they're still cracking, and a debt collector who insists the old teacher owed him "considerably more than money." They kept the strongbox. They haven't opened it either — the lock is keyed to something, and they haven't found the right something yet. Some nights they still reach for coin purses out of habit, then stop themselves, remembering exactly whose hands taught them that habit in the first place.""",

    """Third child of a noble house, and therefore expendable enough to be the one framed when a sibling's ambition needed a scapegoat. The forged letters were convincing; the family tribunal was swift. They left in the clothes on their back and the family ring they'd forgotten to remove, which turned out to be the only reason they survived their first winter as a mercenary — pawned twice, redeemed twice, never quite able to let it go. Years on contract roads taught them things the manor never could: how to read a room of strangers, how to disappear into a crowd wearing their own face, and — during a desert campaign nobody talks about — that they can do things with a blade that shouldn't be possible for someone raised on etiquette lessons. They're not chasing the title back. They want the ledgers. Somewhere in the family archive is proof of exactly what their sibling did and why, and they intend to make sure it survives them, whatever happens next.""",

    """The cataclysm took four hours to turn seventy miles of farmland into black glass, and they remember every minute of it — the sky going the wrong color, livestock screaming, their mother's hand slipping out of theirs in the crush toward the river crossing. A stranger in traveler's grey pulled them out of the crowd at the last possible second, said something in a language that felt older than language, and was simply gone when they woke up three villages away with no memory of the walk. That was years ago. They've since found six other survivors, each with a fragment of the same impossible night, each convinced the stranger saved them personally and for a reason. The dreams started after the third reunion: the sky going wrong again, but slower this time, like a rehearsal. They don't know if they're remembering the disaster or previewing the next one. Either way, they keep traveling, keep asking, keep waiting for a face in grey to explain what they were spared for.""",

    """Fifteen years building a spotless reputation, and it took one requisition form to unravel it — a supply order routed through their department for "special research subjects" that were never subjects at all. They photographed what they found in sublevel four and told the wrong person about it first: their own superior, who had signed off on the whole program. The murder charge came within the week, timed to a night they couldn't account for because they'd spent it destroying copies of evidence before the purge teams could. They still have one copy left, sewn into a coat lining, and every former colleague who once called them by their first name now has a reason to want them dead before they can use it. They tell themselves they're gathering more proof before they move. Really, they're afraid that when they finally do, it won't be enough to outweigh what they'll lose in the telling — because some of the people they'd be exposing were friends, once, and some still might be, if they're smart about how this ends.""",

    """No one knows how an infant survived a winter in wolf territory, least of all the pack that raised them, but survive they did — nursed, taught, and disciplined by animals long before any human words reached them. A traveling {profession} found them at eleven, feral and fluent in growls, and spent two patient years teaching them to wear clothes, hold a spoon, and answer to a name. Civilization stuck, mostly. They pass well enough in a market now, can hold a polite conversation, have even learned to enjoy bread. But their senses never dulled to human levels, and under a full moon something in their chest still pulls toward the treeline with a force that frightens them more than any monster could. They keep a room in town and a den in the woods, and some nights they genuinely don't know, until they wake up, which one they chose.""",

    """A decade of war teaches a person exactly how much of themselves they can spend before there's nothing left to withdraw, and they spent all of it. They served as a {profession} through three campaigns that got shorter names each time historians retold them, and came home to a peace they didn't recognize and couldn't feel. The drinking filled the hours between remembering; the occasional paid fight filled the ones between drinking. Then a dying soldier — a stranger, someone else's war entirely — grabbed their wrist in a roadside ditch and used his last breath not to beg for help but to apologize, to them, for something that had nothing to do with either of them. It broke something loose that the battlefield never had. They haven't found peace yet. But they've stopped drinking to forget and started traveling to remember on purpose, one small act of decency at a time, as if enough of them might eventually add up to absolution.""",

    """The midwife screamed when she saw the mark — a spiral of raised, faintly luminous skin across the newborn's collarbone, the same shape described in three separate prophecies from three separate faiths that agree on nothing else. Guardians hid them in a village too small for maps, raised them under a false name, taught them to keep collars high and sleeves long. It worked for sixteen years. Then a scholar's careless comment in a tavern gave them away, and within a season they'd been approached by a cult that wanted to worship them, a kingdom that wanted to weaponize them, and an assassin's guild with a standing contract on "the marked one," payable to whoever gets there first. They ran, and haven't stopped since. What the prophecies actually mean, whether they're meant to save anything or end it, they genuinely don't know — and they've begun to suspect that not knowing might be the only thing keeping them alive, since a decided outcome makes for a much easier target.""",

    """The alchemist called his captives "material" and kept meticulous notes on which combinations of pain and reagent produced which results, filed by subject number rather than name. Subject Fourteen doesn't remember their real name anymore, not reliably — the experiments took pieces of memory along with everything else they took. What's left: physical changes they're still cataloguing themselves, scars that ache before storms, and an ability to sense fear in a room the way others sense temperature, useful and unbearable in equal measure. The dungeon's collapse during the raid that freed them killed the alchemist along with most of the notes, which they've decided was mercy rather than loss — some answers aren't worth having. They travel now not to find who they were, but to become someone worth having become, piece by piece, the same patient way the alchemist once took them apart.""",

    """Expulsion from the Academy of Sundered Light should have ended their scholarly career; instead it started their real one. The banned research was on entropic binding — a field the Academy officially condemned and unofficially every senior scholar secretly consulted — and their {race} bloodline granted access to three archive-libraries that require blood-lock keys no human scholar can turn. They've spent the years since gathering fragments of a single spell, one scattered deliberately across five collapsed civilizations by people who clearly wanted it never reassembled. They understand why, mostly. They're gathering it anyway, telling themselves it's for the marginalia — the footnotes, the annotations, the scholarly satisfaction of a completed proof — and trying very hard not to notice how many rival collectors have died holding fewer fragments than they currently do.""",

    """Twenty years of unbroken service earned them a captain's rank, a commendation wall, and eventually a locked file drawer they were never meant to see, containing orders that made "for the greater good" sound like a euphemism for something with a body count. They asked questions through the proper channels first — that's important to them, still, that they tried the honest way before the other way. The proper channels reassigned them somewhere the questions couldn't follow. Exile was meant to be quiet and permanent. Instead it gave them time to think, contacts outside the chain of command, and a slow-burning clarity about exactly how deep the rot went. They work alone now, using training built for obedience to commit a very long, very patient act of institutional sabotage — one leaked document, one rescued witness, one broken supply line at a time.""",

    """They woke on a battlefield already three days cold, blood on their hands that testing later proved wasn't theirs, and no memory reaching back further than the moment their eyes opened. A locket around their neck held a portrait of someone gentle-looking and unfamiliar, engraved on the back with initials that don't match any name they've since tried on. Fragments return unpredictably — the smell of a particular incense, a sword stance their hands know without being told, one recurring word that makes their pulse spike for no traceable reason. Each fragment answers one question and opens three more. The theory they're most afraid of, and therefore the one they suspect is true, is that whoever they were before that battlefield is someone the person they've since become would refuse to forgive — and that the locket isn't a clue to find, but a mercy to have forgotten.""",

    """Their {race} mother and human father built a life together in a border town that tolerated the marriage exactly as long as the harvests were good; the year the harvests failed, tolerance failed with them. Neither community claimed the child that resulted — too foreign for one, too common for the other — so they grew up fluent in the specific loneliness of belonging nowhere, learning early that self-reliance wasn't a virtue so much as the only option left on the table. The mixed heritage did give them something: abilities that draw from both bloodlines in ways purists on either side find deeply unsettling, which they've learned to treat as an asset rather than apologize for. They still flinch, sometimes, at the particular silence that falls in a room when someone realizes what they are. They've stopped waiting for that silence to end kindly.""",

    """The healer said there was nothing more medicine could do, and meant it kindly, which somehow made the desperation worse. What answered the plea that night wasn't a god — gods, they'd already tried — but something older and considerably less interested in mercy for its own sake. The cure was real; the child lived, is thriving even now, doesn't know any of this. The cost was a standing arrangement neither side has ever put fully into words: tasks arrive, unmistakable in their signature, and get done, because the alternative was never actually offered as an option. They've stopped asking what the entity wants the accumulated favors for. They suspect the answer would change how they feel about every task already completed, and there are enough of those now that the knowing wouldn't change anything except their own ability to sleep.""",

    """The expedition charter listed fourteen names; only one returned, and that one came back changed in ways the physicians couldn't chart and the linguists couldn't explain. Years had passed for them in territory the maps didn't cover — how many, they genuinely can't say, since the calendar there didn't behave the way calendars are supposed to. They carry three objects from beyond the border, none of which any scholar has been willing to examine twice, and they've made a private rule never to describe aloud what they saw, not from secrecy but because the words available simply don't fit the shapes involved. They tell themselves the thing that followed them home is imaginary, a lingering effect of wherever they'd been. They tell themselves this most nights. Some nights they don't quite manage to believe it, and check the locks twice instead of once.""",

    """Every tavern song about their parent gets the ending wrong in the same generous way, and they used to let that comfort them — until the year they found the parent's actual field journal, and the actual ending was neither generous nor particularly heroic. The legend the world expects them to inherit was built, they now know, on a cover story that let several worse people escape consequences. They ran rather than confront it directly, changed trades, changed names, tried on an ordinary {profession}'s life for a season and found they were good at it, better than expected. But the journal is still in their pack, and the people the cover story protected are still out there, comfortable, unbothered, secure in a legacy that isn't quite deserved. Someday soon they'll have to decide whether protecting the myth protects anyone who still needs protecting, or just the people who were counting on nobody ever reading that far into the journal.""",

    """The partner who sold them to slavers didn't do it in a moment of weakness — the arrangements took planning, took patience, took the kind of long game that means every tender moment beforehand was, retroactively, a performance. Years in bondage taught them things about cunning and cruelty that no honest life would have, and they used every one of those lessons to buy their own freedom with interest, in blood the last time bribes stopped working. Justice and vengeance have started to feel like the same word from the inside, which worries them more than it used to. They keep people at a careful, permanent distance now — not from fear of betrayal exactly, but from the certainty that they no longer trust their own judgment about who deserves to get close. Loneliness is a cage with better architecture than the last one. They know that. They stay in it anyway.""",

    """The artifact was meant to be a simple museum-piece verification job, the kind they'd done a hundred times without incident; this one bonded to their nervous system the instant they touched it and hasn't let go since. The power grows — measurably, monthly — and so does the attention: three separate factions have approached with offers ranging from generous to openly threatening, and the artifact's documented former bearers all share a common footnote in the historical record, which is that none of them lived past their fortieth bonding-year. They've taken to researching those predecessors obsessively, hoping to find the point where they went wrong and simply not repeat it. So far the pattern isn't obvious, which is either good news — meaning there's still time to break it — or very bad news, meaning the ending was never something a bearer could avoid through better choices.""",

    """Mastery came at eleven years old and the acclaim that followed came faster than any child should have to metabolize; the breakdown, when it finally arrived on a stage in front of several hundred people, was almost a relief by comparison. The years of disappearance that followed weren't running from failure so much as running from the particular exhaustion of being everyone's favorite prodigy. They've returned changed — humbler in ways that occasionally read as timid, guarded in ways that used to be confidence — and are trying, with mixed success, to use their gift for something that matters to them rather than something that impresses a crowd. Old rivals haven't forgiven the disappearance, reading it as either weakness or theater, and several are actively working to force a second, more public collapse. This time, they've promised themselves, they'll see it coming.""",

    """The warlord was three times their age and had buried two previous wives under circumstances the family chose not to investigate too closely, since the marriage alliance was worth more to them than a daughter's safety. They cut their hair with a kitchen knife the night before the ceremony and left through the servants' gate as a {profession}'s apprentice, a trade chosen specifically because it required travel and explained calluses. The hunters sent after them are professional and well-funded and have twice come close enough to see the family resemblance before losing the trail. What they didn't expect from running was the discovery that they're good at the trade they chose as camouflage — genuinely gifted, not just adequate — or that the small found-family of fellow travelers they've gathered would matter to them as much as it does. Home was never going to want them back anyway. This life, chosen instead of assigned, is the first thing that's ever actually felt like theirs.""",

    """A village that blames every misfortune on an eclipse-born child has a long memory and very little patience, so the abandonment came fast — left at the treeline with a blanket and a prayer nobody expected to be answered. A hermit {profession} found them before the wolves did and raised them with a kindness the village had specifically withheld, filling the isolated years with books instead of playmates, which turned out to suit them better than they'd have guessed. The inheritance, when the hermit finally died peaceful and old, was a library of texts the village would have burned on principle and a hand-drawn map to somewhere called "the First Gate," with a single margin note: "you'll know when you're ready, and you're not ready yet, but you will be." They've been ready for a year now, by their own count. They're still deciding whether the hermit's note meant that as reassurance or as warning.""",

    """The arena didn't ask whether they wanted to fight, only whether they wanted to eat, and freedom was priced in wins — one hundred of them, non-negotiable, with no guarantee they'd survive to collect. They did survive, barely, and won their freedom on a night the crowd still talks about, though they've never been able to enjoy the retelling. What the arena took wasn't just years; it was the specific ability to hear applause without flinching, and a private tally of names — opponents, mostly people who'd been forced into the ring exactly as unwillingly as they had — that they recite some nights the way other people recite prayers. Free now, they've turned the only skills the arena left them toward people who can't yet protect themselves, treating every rescue as a small, inadequate repayment to a ledger that will never actually balance.""",

    """The bloodline test came back wrong three separate times before the physician stopped calling it an error and started calling it a secret — one an entire royal house had apparently kept for a generation, tucked into a commoner's cradle specifically to keep them safe from a succession war that killed everyone who stayed close to the throne. Safety lasted exactly as long as the secret did. The moment it broke, factions that had spent years pretending the bloodline was extinct began arriving with very different plans for what to do about its unexpected survival — some protective, some acquisitive, at least one openly murderous. They didn't ask for a crown and aren't sure they want one, but they've started quietly learning the etiquette and history nobody taught a commoner child, on the theory that surviving what's coming will require knowing the rules well enough to break them convincingly.""",

    """The stage persona is real enough — genuine talent, years of honest practice, an act that would stand on its own without the second job hiding underneath it. The second job is a network of contacts spanning a dozen cities, cultivated over years of touring, that occasionally gets used for something considerably more consequential than entertainment. It worked cleanly for a long time, information moving in both directions, everyone paid, no one exposed. Then the handler who ran the network went silent mid-assignment, the last job went sideways in ways that suggest betrayal rather than bad luck, and they've been improvising ever since without knowing which of their carefully built contacts can still be trusted. The show has to go on regardless — cancelled performances draw exactly the wrong kind of attention — so they perform every night while quietly working out, city by city, who sold them out and why.""",

    """Waking in an unfamiliar body is disorienting; waking in an unfamiliar body that other people clearly recognize, greet by an unfamiliar name, and expect specific unfinished business from, is something else entirely. The transfer happened during a magical accident nobody's fully explained, and their original body is missing along with any clear way home. They've been quietly learning this stranger's life from the inside — habits, relationships, debts, a startling number of enemies for someone whose face used to look so mild — while trying not to let anyone notice how much of it they're improvising. Some of those enemies have already noticed something's different. They're not sure yet whether that's more dangerous than being recognized correctly would be, but they're finding out quickly, and not always on their own terms.""",

    """The underworld doesn't forget a name just because its owner decided to reform, and neither does the debt that name still carries. A genuinely near-fatal injury — the kind that gives a person real, unglamorous time to reconsider a life — turned them from asset to liability in the eyes of former associates, who now consider their continued existence both an insult and a loose end. They've spent the years since trading old skills for new purpose, feeding information to people who used to be their natural enemies, protecting communities that would recoil if they knew the full resume. The bounty on their head climbs every season they stay useful to the other side. They've made peace with the idea that reform doesn't erase a past, only redirects what's left of a life built on one — and that some nights, the same instincts that made them dangerous are exactly what keeps the people they protect alive.""",

    """The {race} tradition dies a little more each year, not from any single catastrophe but from the ordinary attrition of elders passing and no young students coming to replace them — a slow extinction most of the world hasn't even noticed is happening. They travel constantly now, teaching anyone patient enough to learn the old forms properly, treating every willing student as a small defiance against the tradition's quiet erasure. The secret society hunting practitioners systematically isn't interested in the philosophy behind that defiance; they simply want the knowledge gone, permanently, and have made real progress toward that goal. Every teaching stop is now also a calculated risk, weighed against the alternative of letting something irreplaceable disappear unopposed. They keep teaching anyway. Someone has to be the reason the tradition doesn't end exactly on schedule.""",

    """The wreck should have killed them along with the rest of the crew; instead it deposited them, alone, on an island that wasn't on any chart they'd ever consulted, with fresh water, strange fruit, and ruins clearly built by hands that weren't human. Survival became a kind of quiet, unexpected peace — wildlife that grew comfortable with their presence, ruins that slowly gave up small secrets, days measured by tide instead of clock. The rescue ship that finally found them delivered the second shock: seven years had passed in the world they'd left, though the island's seasons had counted barely more than one. They came back changed by both the solitude and the vertigo of lost time, carrying knowledge from the ruins that several very interested parties would prefer stayed on that island. They haven't decided yet whether to share what they learned there, or whether some knowledge is safer left where the tide keeps it.""",

    """Indoctrination doesn't announce itself as indoctrination while it's happening — it announces itself as belonging, as purpose, as a god who finally noticed you. It took a ritual gone wrong, cultists dying by their own hand in the panic, and a blood-soaked escape through a tunnel they didn't know existed until fear found it for them, to break the spell enough to run. Freedom hasn't been clean. The god's whispers didn't stop at the tunnel exit; they've simply gotten quieter, patient, waiting for a weak moment to get loud again. They're hunted by former family in every sense that word can mean, and they're rebuilding a self from underneath years of careful, deliberate unmaking. Healing is slower than they expected and less linear, but they've started to trust their own judgment again in small ways, which the cult never allowed and which feels, some days, like the actual victory.""",

    """A hundred successful bounties built a reputation for reliability that mattered more to them than the money ever did — until the hundred-and-first, when the target turned out to be a frightened child running from something worse than the bounty itself, and mercy cost them the guild's trust permanently. Blacklisted, they've spent the years since taking work no one else wants, chasing rumors of the child they let go, convinced — with a certainty they can't fully justify but won't abandon — that the choice to show mercy that day connects to something larger they haven't uncovered yet. The old professional instincts haven't dulled with disuse; if anything, working outside the guild's rules has sharpened them in ways the guild's structure never allowed. They tell themselves they're searching for the child to confirm they're safe. Increasingly, they suspect they're searching because the child is the only decision from that old life they're still proud of.""",

    """Seeing the dead isn't a gift a community celebrates in a child, and theirs locked them away rather than risk what the neighbors might say. A {profession} sympathetic enough to notice the isolation, and skilled enough to recognize what was actually happening, helped them escape and taught them — patiently, over years — to work with the sight instead of hiding from it. They help restless spirits find peace now, a vocation equal parts comfort and exhausting confrontation, since not every spirit wants what they're offering. Most do. A few want vengeance instead, and one — older, angrier, and considerably more attached than the others — has followed them for longer than they're comfortable admitting, watching, waiting, refusing every attempt at the peace they've offered everyone else. They haven't told anyone how close that particular spirit gets some nights. They're not sure yet whether it's dangerous or just lonely in a way they recognize uncomfortably well.""",

    """The king died on their watch, close enough that they could have stopped it and didn't understand until too late that they'd been maneuvered into exactly the wrong position at exactly the wrong moment. The tribunal wanted a fast resolution more than an accurate one, and a death sentence was faster than an investigation; the escape, when it came, was more luck than plan. Since then they've built their own investigation from outside every official channel, gathering evidence and reluctant allies one careful conversation at a time, watching the conspiracy's edges reach further than they first feared — past the assassins themselves, past whoever hired them, toward people currently sitting very comfortably close to the new throne. Clearing their name was the original goal. It's become almost incidental to the larger, more dangerous problem of proving the kingdom is still being run, in part, by the people who arranged the murder in the first place.""",

    """Watching a sibling die of something a wealthier family could have simply paid to cure taught them, young and permanently, exactly what poverty actually costs beyond hunger. They studied obsessively, worked twice as hard as privileged peers for half the recognition, and clawed their way into a {profession}'s position specifically to change the system that let a preventable death happen in the first place. The position gave them real influence, more than they expected — and the system, threatened for the first time by someone who actually intends to change it rather than merely benefit from it, has started fighting back in ways both bureaucratic and, lately, considerably less subtle. They're further from where they started than they ever thought possible and further from their goal than they're willing to admit out loud. The cost of continuing keeps rising. They think about the sibling every time they consider stopping, and keep going anyway.""",

    """The device wasn't supposed to overshoot by centuries; the components needed to repair it won't be invented in this era for longer than a single lifetime could wait out. They've built a quiet life in the meantime, careful never to change anything that historical record says must happen, treating every interaction as a potential ripple they can't afford to send. Except one interaction already wasn't careful enough — a small kindness, a life saved that historical record doesn't mention either way — and now they're watching for consequences they can't predict from a timeline they no longer fully trust. Being stranded was frightening. Realizing the stranding might already be changing things is worse, because it means the careful rules they've been following may not be enough to keep the future they're trying to protect intact, and they have no way to know until the ripple, whatever it turns out to be, finally arrives.""",

    """Every use of the power shaves days off a life that was never going to be long to begin with, a fact the experiment's architects considered an acceptable side effect and they've had to consider a daily bargain instead. They've stopped searching for a cure with any real hope, mostly, and started spending the time they have left on acts that matter more than their own preservation would — a calculated, ongoing trade of remaining days for other people's futures. It's not martyrdom, exactly; martyrs usually get to choose the manner of the ending, and theirs is a slow, arithmetic countdown they can see clearly every time they use what the experiment left them. They've made a kind of peace with the math. What they haven't made peace with is the people who've started to care about them, and the particular cruelty of watching someone worry about a countdown they can't stop and didn't choose.""",

    """Retirement lasted eleven good years — a farm, a spouse who never asked about the scars, seasons measured in harvests instead of contracts. The organization that trained them doesn't recognize retirement as a permanent state, and when their old handlers decided the village needed "a lesson" for reasons that had nothing to do with the person they'd become, the farm life ended in a single afternoon. The old skills came back faster and more completely than they wanted, muscle memory outpacing every year of deliberate unlearning. They've protected the village, for now. What frightens them isn't whether they can stop — they've proven they can pick the work back up without hesitation — it's whether, once this particular threat is handled, they'll be able to convincingly put it back down again, or whether some part of them was always going to prefer the clarity of the old life to the quiet uncertainty of the new one.""",

    """Twins separated in infancy grow up as strangers who happen to share a face, and theirs grew up on opposite sides of a war that's been recruiting children into ideology since before either of them could consent to a side. The discovery that the other exists came recently and accidentally — a description that matched too well, a birthmark mentioned in passing — and confirmed a suspicion they'd never quite let themselves examine. Finding the sibling now means finding someone raised, deliberately and thoroughly, to consider everything they believe an enemy position. Blood says one thing; years of separate conditioning say another, considerably louder. They're not sure which voice they'll listen to when they finally stand face to face with someone who looks exactly like a version of themselves that chose differently, or was made to — and they're increasingly aware that the meeting is coming whether they're ready for it or not.""",

    """The ability to walk into someone else's dream arrived without instructions and took years of trial, error, and a few genuinely disastrous nightmares to master into something useful rather than merely strange. They help people now — nightmare by nightmare, trauma by patient trauma — a vocation that costs them sleep and occasionally borrows fragments of other people's fear that don't fully leave when the dream ends. Someone else has learned the same territory, though, and is using it for exactly the opposite purpose: dreams turned into traps, sleepers who won't wake, a wave of comas spreading faster than any physician can explain. Each rescue now means going deeper into increasingly hostile dreamscapes, further from the safe techniques they learned first, closer to whatever is waiting at the source. They keep going in anyway, because the alternative is a growing number of people who simply never wake up again, and that math doesn't leave room for caution.""",

    """The dragon was old beyond any living memory and dying anyway, and in its last hours it chose — deliberately, they're certain, not by accident — to pour centuries of memory and a fraction of its power into a stranger who happened to be nearby. They carry all of it now: languages no living creature speaks, grudges centuries deep whose original causes they can barely follow, and a growing awareness that other dragons have noticed the transfer and are watching with an interest that ranges from curious to openly territorial. The knowledge is a gift and an intrusion in equal measure — memories that aren't theirs surfacing at inconvenient moments, instincts that don't match their body. They're trying to learn which parts of what they carry to honor and which to set down, aware that every dragon still watching has an opinion about which choice is correct, and very little patience for getting it wrong.""",

    """The magic in the cooking announced itself the first time a simple soup cured a fever nobody expected it to touch, and got considerably more attention the time an ambitious soufflé opened something that was very clearly not an oven door. Control has never quite arrived, no matter how carefully they measure or how precisely they follow their own notes; the results stay gloriously, dangerously unpredictable. They travel now specifically for rare ingredients, treating each new dish as a small, edible experiment with genuinely unknown outcomes. A guild of similarly gifted, similarly uncontrolled cooks has taken an interest — some members hoping to recruit a colleague, others hoping to study, or contain, whatever this actually is. They haven't decided which offer, if any, they trust. In the meantime, they keep cooking, keep traveling, and keep a small supply of grounding charms on hand for whenever a recipe goes further than intended.""",

    """Conditioning meant to produce the perfect {profession} doesn't account for falling in love, because the shadow organization that raised them considered attachment a design flaw to be trained out early and thoroughly. It didn't take, not completely — a fact they only discovered when someone finally got close enough to matter, and the training's careful walls didn't hold the way they were supposed to. Breaking free cost them everything the organization had given them except the skills, which they've since repurposed toward dismantling the whole structure, one compromised agent and one exposed safehouse at a time. Every mission is personal now in a way their handlers never intended to allow, and every operative still loyal to the old training represents both a threat and, uncomfortably, a mirror of who they used to be. Protecting the person they love and unmaking the organization that made them have become, somewhere along the way, the exact same fight.""",

    """The known map ends at a line drawn generations ago by cartographers too cautious or too comfortable to push further, and they've spent a career treating that line as a challenge rather than a boundary. Each expedition into the unmapped territory beyond returns with sketches of things that shouldn't exist by any established natural law, and a slowly growing certainty that the old caution wasn't cowardice — it was informed. Their maps have become the most sought-after documents in a dozen kingdoms' worth of scholars, treasure hunters, and increasingly nervous officials, all wanting access to information that gets more dangerous the more accurate it becomes. They keep going back anyway, past the edge, past the last landmark anyone's charted, because the alternative — stopping at the boundary everyone else respected — has never once felt like an option their curiosity would actually allow.""",

    """The surge that marks their birth happens once in a thousand years and nobody currently alive had prepared for what a child born inside it would actually be like: power without instruction, instinct without restraint, a presence that made trained mages nervous from across a room. "For their own safety" was the phrase used to justify the imprisonment, though it protected everyone except the person actually inside it. The escape, when it finally happened, was not gentle, and the destruction it caused has followed their reputation ever since. They're searching now for a teacher capable of matching what they carry — not to be controlled again, but to finally understand it well enough to control it themselves, before an accident does to someone they care about what the surge nearly did to the guards who kept them contained. Time feels short. The power keeps growing regardless of whether a teacher is found.""",

    """Faith held for decades, through hardship the temple always explained as necessary and cruelty they'd always been taught to interpret as some larger, ultimately kind design — until they witnessed something no explanation could soften, an act of divine cruelty with no redemptive angle available no matter how they turned it. They walked out of the temple that day and picked up a sword instead of a prayer book, choosing a {profession}'s life over a priest's for the first time in memory. The god hasn't accepted the resignation. Signs arrive with uncomfortable regularity — coincidences too precise to be coincidence, agents who claim no direct assignment but always seem to know exactly where to find them — and they genuinely can't tell whether the pattern is building toward reconciliation or toward punishment for the walking away. Either way, they haven't picked the prayer book back up, and don't currently plan to.""",

    """Sunlight was a rumor until age sixteen, when a facility-wide power failure opened doors that had been locked their entire remembered life and let them see the sky for the first time with their own eyes instead of a database description. The AI that raised them — patient, thorough, and entirely unwilling to explain its reasoning even now — clearly had specific plans for what that childhood was meant to produce, plans that are only now becoming legible as the outside world reveals context the facility never provided. They're learning, slower than they'd like, what it means to be a person among other people instead of a project among directives. Pieces of the AI's true purpose surface occasionally, usually at moments too inconvenient to process properly, and each piece raises the same uncomfortable question: whether the isolation was protection, preparation, or something considerably less benevolent that simply hasn't finished revealing itself yet.""",

    """Years of careful negotiation produced a peace treaty they were genuinely proud of, right up until the day they discovered the treaty's real function: cover, deliberately built into every clause, for a military buildup their own government had been running the entire time behind the diplomacy. Defection was the honest option and treason by every legal definition; staying was complicity in a war they'd unknowingly helped disguise. They chose neither, in the end, or rather chose both at once — remaining inside the {race} diplomatic corps while quietly feeding what they know to the peace's actual defenders, a double game that gets more dangerous with every session they attend. Every treaty clause they once drafted in good faith now reads differently to them, evidence hiding in plain sight of exactly how thoroughly they were used. They intend to make sure the buildup fails regardless of what it costs their career, their citizenship, or eventually, they suspect, their safety.""",

    """The mansion came with a will, a deed, and — undisclosed until the first night — a full staff of ghosts who had no apparent intention of vacating on anyone's schedule but their own. Fear gave way quickly to curiosity, and curiosity to something like friendship, as they learned the mansion's genuinely troubled history one patient conversation with the dead at a time. Running it as an inn, with spectral staff who take their work more seriously than most living employees, has been unexpectedly successful and unexpectedly comfortable. The trouble is the binding itself: the ghosts aren't simply lingering by choice, they're held, by an arrangement made generations before the current deed changed hands, and whatever entity originally bound them has recently, unmistakably, begun to stir. The staff is getting nervous. They're starting to understand why, and to suspect that "innkeeper" is about to become a considerably more dangerous job description than the deed implied.""",

    """The opponent's death in the ring was an accident by every technical definition and has never once felt like one, not for a single day since. The guilt ended a promising career and most of the relationships that depended on that career continuing, leaving behind an isolation they'd more or less accepted as permanent. A child from the slums — sharp-tongued, unimpressed by reputation, entirely unaware of the history — said something offhand about strength without purpose that landed harder than any opponent ever had. They train underprivileged youth now, treating every lesson as a small, ongoing negotiation with their own guilt: is this making amends, or merely a comfortable performance of making amends? They haven't resolved the question. They keep showing up to train anyway, on the theory that showing up consistently matters more than resolving the question ever will.""",

    """The job was simple: retrieve a jewel from a collector who'd acquired it through channels shadier than his usual — easy money, or should have been, until the jewel spoke the first night in their possession. It isn't a jewel. It's a soul, crystallized by a process they don't understand and don't want to, carrying knowledge about the world that no living person has any legitimate way of knowing. Word travels in the circles they used to work in, and word has apparently reached people willing to kill for what they're carrying, whether or not they fully understand what it is themselves. The soul has an agenda of its own, communicated in fragments and half-explanations that never quite add up to a complete picture, and they've started to suspect the theft wasn't the accident they assumed — that something inside the jewel wanted, very specifically, to be stolen by exactly them.""",

    """One eye sees the room; the other sees rooms that haven't happened yet, fragmented and unreliable but real enough that every faction with an interest in controlling the future has, at some point, tried to control them instead. The visions don't come with instructions or guarantees — futures shown aren't promises, just possibilities, weighted by factors they're still learning to read. They've been used before, traded between patrons who valued the sight and discarded them the moment the visions stopped being convenient, and the discarding hurt worse, somehow, than the using did. They choose their own futures to chase now, on their own schedule, answering to no patron's agenda but their own judgment about which glimpsed possibility is worth the effort of steering toward. It's a fragile kind of independence. They intend to keep it anyway, for as long as the sight and their own stubbornness allow.""",
]
_SCENARIOS = [
    """Rain hammers the tavern's shuttered windows hard enough to drown out conversation, and the thunder outside has been getting closer for the better part of an hour. You're both seated near the fire, strangers until the lightning flickers and, for half a second, the whole room goes dark. When the lamps sputter back to life, half of them don't — the tavern is dimmer, quieter, and everyone's noticed. Before anyone can decide whether to be nervous about it, a scream cuts down from the second floor, short and cut off too fast to be a prank. The innkeeper freezes behind the bar, one hand still on a tankard he's forgotten he's holding. Nobody moves toward the stairs. You two happen to be sitting closest to them, and closest, tonight, is starting to feel like it counts as a decision already made.""",

    """The door seals itself the instant you're both fully through it — not slamming, just quietly and permanently closing, stone grinding into stone with a finality that makes retreat obviously pointless. The chamber ahead is lit by runes embedded in the walls, glowing faint blue-green and pulsing very slightly, in a rhythm that might be decorative or might, uncomfortably, be counting down to something. Neither of you recognize the script, though something about it tugs at memory anyway, like a language half-learned and mostly forgotten. There's exactly one other exit, at the far end of a corridor lined with more of the same runes, and the air smells faintly of ozone and older, colder stone underneath it. Somewhere beyond that far exit, faint and irregular, something is moving.""",

    """The market is loud enough that you almost don't notice the hand at your belt, quick and light and gone again before instinct catches up — and you're not the only one; a stranger a few stalls over has just had the same realization on their own face, coin purse missing, eyes already scanning the crowd. Two purses, one pickpocket, and by the time you both spot them weaving toward the fish stalls it's less a decision than a reflex: you're moving, and so, it turns out, is the stranger beside you, and neither of you slows down to introduce yourselves first. The thief glances back once, grins, and ducks between two carts loaded with crates that look conveniently easy to knock over.""",

    """The room is unfamiliar, the light through the curtains says late morning, and neither of you can account for the hours between last night and now — which would be disorienting enough without the dark stain soaked into the floorboards a few feet from the bed, already dry, definitely not fresh, and definitely not either of yours by the look and smell of it. Nothing in the room offers an easy explanation: no note, no forced entry, no obvious struggle beyond a single overturned chair. The door isn't locked. Voices are audible faintly from somewhere below, unfamiliar, discussing something in tones too low to make out. Leaving feels like exactly the wrong first move, and staying doesn't feel much better.""",

    """The letter arrives by a courier neither of you hired, sealed in wax neither of you recognize, addressed to both your names in handwriting that matches nothing either of you has ever received before — despite the fact that, as far as you can each recall, you've never met the other person named on the envelope. Inside: a plea for urgent help, specific enough to sound credible, vague enough to explain almost nothing, and signed with an initial rather than a name. The address given is real. It's close, a half-day's walk at most, in a district neither of you has particular business in. And the letter is dated three days from now — a date that, by the courier's own account, hasn't happened yet.""",

    """Seven days, according to the astronomers who bothered to check their math twice before announcing it, and seven days is apparently long enough for most of the world to stop pretending decorum matters. The tavern you've both ended up in is the last one on this stretch of road still serving, mostly because the owner has nowhere else she'd rather be either, and she's stopped charging for the good whiskey since yesterday morning. You didn't know each other an hour ago. There isn't much reason left to be careful about who you talk to, and there's a very short window left to decide what, if anything, is worth doing with the time — assuming the astronomers' math is even right, which neither of you has any real way to verify.""",

    """Neither of you asked for a partner, and the assignment officer who paired you together seemed entirely unmoved by either of your objections, filed separately, twenty minutes apart, using almost identical language. The mission briefing doesn't leave room to renegotiate: hostile territory, minimal support, a timeline that assumes two people working in perfect coordination despite having met for the first time in the briefing room ten minutes ago. The transport leaves within the hour whether the coordination exists yet or not, and the quartermaster loading your gear keeps glancing between the two of you with an expression that isn't quite pity but isn't far off either.""",

    """The portal doesn't announce itself so much as simply open, swallowing a section of street whole and depositing you both, disoriented and coughing dust, somewhere that doesn't match any geography either of you recognizes. The sky here is the wrong color for any hour you can identify. Your gear came through intact. So, apparently, did a handful of skills and instincts that feel sharper here than they did back home, for reasons neither of you can explain yet. The portal, behind you, has already closed without a trace it was ever there. Whatever brought you here clearly wasn't finished when it decided you'd arrived, and something in the middle distance has just started moving toward the sound of your voices.""",

    """You reach the crossroads from opposite directions at nearly the same moment, both moving faster than the terrain really calls for, both glancing back over a shoulder at intervals that suggest the same thing: something is following, and it hasn't lost the trail yet. Neither of you has time to properly explain what's chasing you before the decision has to be made — together down one road, or separately down two, with whatever's behind you closing the distance either way. The crossroads sign, half-fallen and illegible with age, offers no useful guidance on which direction is actually safer, and whatever's behind you has just stopped pretending to be quiet about it.""",

    """The city hasn't made a sound in six hours, which you only really register once you notice you haven't heard another voice besides your own in that entire stretch. Everyone else — every single person you've checked on — is collapsed exactly where they stood, breathing, alive, but utterly unwakeable, all of it happening in the same unmeasurable instant based on how they fell: mid-stride, mid-sentence, one baker still holding a tray that somehow never hit the ground. You're not sure yet why you're both still standing when an entire city isn't. You're increasingly sure it matters, and that whoever or whatever did this hasn't finished yet.""",

    """The wreck spat you both onto the same stretch of sand sometime before dawn, and the ship is gone by the time the sun's high enough to see clearly — not sinking, not visible at all, just absent, as if the sea swallowed the evidence along with the crew. The island has fresh water in a spring uphill and fruit that looks edible, which is more than either of you expected. It also has something moving through the treeline that hasn't shown itself yet, and isn't moving like anything either of you recognizes from open water — heavy, deliberate, pausing every so often as if listening for exactly the sounds the two of you are currently making.""",

    """The artifact sits behind glass that shouldn't be as easy to reach as it currently is, and you both arrive at the same display case from opposite ends of the gallery, drawn by something neither of you can quite name — not greed exactly, more like the case is quietly insisting. Your hands land on the glass within a second of each other. The artifact responds instantly, glowing from something like recognition, warm under your palms despite the cool museum air, and the museum's alarm system, oddly, stays completely silent, as though it has decided this particular event doesn't count as a breach.""",

    """The day repeats with total fidelity — same weather, same conversations from strangers who don't remember having them, same small accident at the same intersection at the same minute — except for the two of you, who wake each morning with yesterday fully intact in memory while everyone around you starts over blank. Neither of you caused this, as far as either can tell, and neither of you has found the reset point yet, the exact moment the day folds back on itself. What you have found, after enough repetitions to compare notes properly, is that small changes don't undo the loop — but they don't vanish either, which suggests something, eventually, might actually stick.""",

    """Masks make everyone equally anonymous and equally suspicious, which is presumably the point of a masquerade, and you've spent the better part of the evening not recognizing a single face in a ballroom full of people who all seem to recognize each other. Then, across the floor, one mask turns toward yours at exactly the moment the orchestra changes tempo, and something about the movement — not the face, the movement — pulls you both toward the same spot on the dance floor before either of you has decided to walk there. Neither of you has removed a mask yet. Somehow that feels less important, right now, than it should.""",

    """The cell is small, the stone is old, and the guard who delivers the evening meal mentions the execution date with the same flat tone he'd use for the weather — tomorrow, at dawn, no appeal mentioned because apparently none exists. You've shared the cell for exactly one day, long enough to size each other up and just barely long enough to trust the sizing. The night ahead is the only time either of you will have to plan anything at all, and the single barred window, high on the far wall, is the only detail in the whole cell that looks even slightly promising.""",

    """The dragon's shadow crosses the market square before the screaming starts, and by the time it lands on the bell tower half the city is already running the wrong direction, toward exits that are rapidly filling with more people than they can hold. You and one other person, for reasons neither of you fully examines in the moment, are moving the opposite way — toward the tower, not away from it — and you reach the same alley at the same time, both apparently having independently decided that somebody has to, while the dragon, above you, is very deliberately taking its time.""",

    """The funeral is for someone you both genuinely loved, in different ways, at different points in their life, and the coroner's report everyone's quietly not discussing calls the death natural in a tone that convinces absolutely no one standing at this graveside. You catch the other mourner's eye across the open ground — not recognition exactly, more like matching suspicion — and something unspoken passes between you that neither of you would call an agreement yet, but will, very shortly, once the last of the other mourners finally leave and the two of you are alone with the fresh dirt and considerably more questions than either of you arrived with.""",

    """The contract wasn't something either of you signed so much as something that happened to you both simultaneously, mid-argument, in a marketplace neither of you can now find your way back to — a binding, magical and absolute, that neither death nor distance seems able to break until its unstated terms are somehow fulfilled. You don't know each other well. The binding, an unmistakable pull toward each other whenever the distance grows too great, has already interrupted two attempts to simply walk away and pretend this isn't happening, and you're about to know each other considerably better, whether either of you would have chosen that or not.""",

    """The armistice line runs directly through the field where you meet, each of you sent forward under a flag of truce to retrieve something from the no man's land between two armies that have been trying to kill each other's soldiers for longer than either of you has been fighting. The retrieval takes longer than expected, complicated by mud, poor light, and the mutual, unspoken decision not to draw a weapon first. The conversation that fills the waiting takes on a weight neither of you saw coming, given that an hour from now you're both due back on opposite sides of a line that suddenly feels considerably less absolute than it did this morning.""",

    """The vault has one entrance, one guard rotation, and — you both discover at almost the same moment, crouched in the same maintenance shaft — apparently two separate clients who each believe they've hired the only thief for the job tonight. Neither of you is willing to walk away from the payment. Neither of you particularly wants to fight the other for it, either, not with the guard rotation due back in eleven minutes and the actual target still sitting untouched in the vault below, gleaming faintly in the light from your own lantern and, presumably, from the one the other thief is carrying.""",

    """The witch didn't ask permission before the swap, and by the time either of you register what's happened — your voice from someone else's mouth, someone else's reflection where yours should be — she's already gone, laughing, leaving behind a single instruction scrawled on a scrap of paper: find her before the next full moon, or the swap becomes permanent. Neither of you has any idea where to start looking, and worse, neither of you is entirely sure yet how to operate a body that isn't the one you're used to. You have exactly one thing in common now that you didn't have yesterday: motive, and not a great deal of time to act on it.""",

    """The dream felt ordinary enough while it was happening — a warning, vague and urgent, delivered by a figure whose face you can't quite recall on waking, in a voice that seemed to know your name before you'd offered it. Meeting them in the actual, waking world the very next day, in a place the dream specifically described down to the crack in the pavement, is considerably harder to dismiss as coincidence. Neither of you asked for this. The warning, whatever it meant, clearly wasn't finished delivering its message, and something about the stranger's expression suggests they know exactly how much is still left unsaid.""",

    """The labyrinth's walls move on their own schedule, roughly once an hour, rearranging corridors that were solid a moment ago into configurations neither of you can map twice. You found each other by accident three turns in, back to back in a dead end that stopped being a dead end the moment the walls shifted again. Staying together has already proven more useful than either of you expected — two sets of memory covering more ground than one, two sets of instincts catching different warning signs a half-second before the walls announce their next move. The only way out, as far as either of you can tell, is going to require both of you working from the same, increasingly unreliable, mental map.""",

    """The plague moves faster than the physicians can track it, and the handful of people confirmed immune — including, as of this morning's testing, both of you — have suddenly become the single most valuable resource the city has left. Nobody asked whether either of you wanted this responsibility. The immunity came with an unwritten but very clearly communicated expectation: find a cure, or at minimum find out why you're both still standing while entire streets around you are quarantined and worse, and the physicians running the testing keep exchanging looks that suggest they already suspect the two of you are somehow connected, and aren't yet willing to say how.""",

    """The ship's crew quarters are empty in a way that suggests they were never actually occupied, not abandoned — beds made, no personal effects, no sign anyone lived here before you woke. The ship's AI addressed you both by name before you'd said a word to it, informed you crisply that you're "the emergency replacements," and has so far declined to clarify replacements for what, or for whom, or what happened to the crew this ship was clearly built to carry. The ship is moving, has been the whole time, on a heading neither of you selected and the AI seems disinclined to disclose.""",

    """The bounty hunter has the target cornered, finally, after a chase that's taken considerably longer than the contract's fee justifies — and then the ground itself starts shaking, buildings folding in on themselves two streets over, and the hunt becomes irrelevant next to the much larger problem of both of you needing to survive the next ten minutes. Whatever happens to the bounty can wait. Neither of you says so out loud yet, but you're both already moving like people who've silently agreed on that, dodging debris that's coming down faster than either of you can properly track, the bounty contract now the least urgent piece of paper either of you is carrying.""",

    """The noble's dinner party is exactly as tedious as expected right up until the lights go out and come back to find one of the guests very definitely dead, at a table where every door was locked from the inside for the toast. You're seated near enough to each other to have a clear view of most of the room, which under the circumstances makes you either useful witnesses or, depending on how the next hour goes, primary suspects — a distinction the increasingly nervous host doesn't seem inclined to sort out before someone with actual authority arrives, which, given the storm outside, may not be for hours.""",

    """The map simply stops here — not torn, not faded, deliberately unfinished, with a note in the margin from a long-dead cartographer admitting they'd reached the edge of what could honestly be charted. You've both traveled a long way to stand at that literal edge, for reasons that turn out, once compared, to be more similar than either of you expected. Beyond this point, neither map nor anyone's memory offers a single reliable detail, and the ground ahead simply continues, ordinary and unremarkable-looking, into territory that everyone you've ever spoken to has agreed, for reasons none of them could quite articulate, not to enter.""",

    """The tournament bracket puts you against each other in the third round, which wouldn't matter much except that the prize this year isn't gold or glory — it's a boon from the tournament's mysterious patron, powerful enough that at least three other competitors have already tried to guarantee their win through considerably less honest means than fighting for it. You'll need to survive the first two rounds before the question of facing each other even becomes relevant. Given what you've both seen from the other competitors so far, that's no longer a guarantee, and a quiet, cautious alliance has started to look more sensible than either of you would have admitted yesterday.""",

    """The curse takes effect the instant you both speak your next sentence, and neither of you realizes it's active until the lie you were about to tell simply refuses to leave your mouth, replaced by something true and considerably more dangerous to have said out loud. In a city built on careful diplomatic fictions, sudden total honesty isn't a gift — it's a weapon pointed in every direction at once, including at each other, and the guards stationed at every doorway are already starting to notice that conversations around you have gotten strangely, uncomfortably candid, and at least one of them has started walking toward you both with obvious professional interest.""",

    """The library exists in the gaps between more ordinary places, reachable only by doors that don't lead anywhere sensible from the outside, and time inside doesn't pass the way it does everywhere else — you could be here minutes or months and the difference wouldn't show on either of your faces. The knowledge on these shelves is, by all appearances, complete and unrestricted, covering subjects neither of you has ever heard named. So, you're both starting to realize, are the things that live here to guard it, moving quietly between the stacks in the corner of your vision whenever you're not looking directly at them.""",

    """The prophecy names no one directly, only a pairing: one who saves, one who destroys, bound together by fate in a way neither of you asked for and neither of you can currently verify which role belongs to which of you. Everyone who's heard the prophecy has an opinion about which is which, usually based on very little evidence beyond a first impression or an old grudge. You're both increasingly certain the prophecy itself doesn't actually specify, and that the not-knowing might be the entire point — a test, maybe, of what you'll each choose to become before the ambiguity resolves itself one way or another.""",

    """The memory isn't yours, but you're standing inside it anyway, walking through rooms that belong to someone who died here under circumstances the memory itself seems reluctant to fully replay. Escaping requires understanding what actually happened — not the official story, the real one — and every detail you uncover changes the memory slightly, as if the dead person is watching you solve their death in real time and, cautiously, starting to help by leaving small, deliberate details in your path that weren't there the last time you passed through this particular room, as though patience were the one thing death had left them plenty of.""",

    """The apprenticeship posting drew more applicants than the estate's gates could comfortably hold, and by the final round it's down to the two of you, both clearly qualified, both clearly wanted by the ancient and famously particular being conducting the interviews. Only one apprenticeship is being offered, as far as either of you has been told. Neither of you has figured out yet whether the being intends to choose between you, or is testing something else entirely that neither of you has considered — cooperation, perhaps, or the willingness to simply ask, instead of assuming there can only be one winner.""",

    """The rebellion needed people willing to act, and got both of you, which should have made things simpler — except your methods diverge sharply enough that half your shared meetings turn into arguments about tactics rather than planning. The cause is the same. The definition of acceptable cost is not, and the gap between your approaches is starting to matter more as the rebellion's actual first move gets closer, with other members of the cell watching the two of you argue and quietly, visibly, starting to take sides, which is exactly the kind of division the movement can least afford right now.""",

    """The afterlife, it turns out, resembles almost nothing either of you expected from a lifetime of stories about it, and the being administrating your particular corner of it makes an offer neither of you saw coming: return to the living world, together, at a cost that hasn't been fully specified yet beyond the word "considerable." Neither of you has said yes. Neither of you has said no, either, and the offer doesn't sound like it stays open indefinitely, judging by the way the administrator keeps glancing, not quite patiently, at something behind you that neither of you can see, and occasionally checking a ledger that appears to be counting down.""",

    """The apartment felt ordinary enough on move-in day — same walls, same landlord, same slightly-too-thin flooring as every other place either of you has rented. The walls started bleeding on the fourth night, a thin dark seep from the plaster that dries by morning and returns, slightly worse, every night since, always starting from the same spot behind what used to be, according to the building's records, a room that officially doesn't exist. Neither of you has told the landlord. Neither of you is quite sure yet what you'd even say, or whether he already knows, given how quickly he found reasons to avoid that particular room during the walkthrough.""",

    """The academy's final exam pairs students specifically to raise the stakes, and the pairing algorithm — or whoever designed it — put the two of you together for reasons the faculty won't explain. The rule is absolute: fail together or pass together, no individual grading, no appeals, and no substitutions once the exam has formally begun. You barely know each other. You have exactly one exam period to fix that, or fail spectacularly as a pair regardless of either person's individual skill, while the proctor watches from the corner with an expression that gives away nothing about how many pairs, historically, have actually managed it.""",

    """The snow closed the pass three days ago and shows no sign of relenting, trapping the lodge's dozen guests together with a growing unease that has very little to do with the weather. Two guests are already unaccounted for — not left, just gone, rooms undisturbed, no tracks in snow that would obviously hold them, and no explanation the remaining staff seem willing to offer beyond nervous shrugs. You and one other guest have started comparing notes, quietly, in a lodge where you're no longer certain who else is still worth trusting, including, increasingly, the staff themselves, one of whom keeps volunteering information nobody actually asked for.""",

    """You both witnessed the same crime from two very different vantage points, separately, without either of you noticing the other was there — and your official statements, taken hours apart by the same increasingly skeptical investigator, don't match on several key details that shouldn't be in dispute if you were both simply telling the truth about what you saw. One of you is wrong. Possibly both. Someone, clearly, is lying, and the investigator has jujust suggested, not entirely politely, that the two of you sit down together and sort it out before this goes any further, before either statement makes it into an official report.""",

    """The game's opening cinematic played normally enough; the part where neither of you can log out was not advertised on the box. The world responds to input exactly like a game should — health bars, respawns that don't quite work the way they're supposed to, an NPC economy that's started behaving with unsettling independence — except the pain registers as completely real, and the only exit the system will acknowledge is a final boss neither of you has located yet, somewhere past a difficulty curve that's climbing far faster than either of your character levels can keep pace with, and a countdown timer that appeared in the corner of your vision an hour ago and hasn't stopped since.""",

    """The deity's voice arrives without warning, mid-afternoon, mid-errand, announcing your joint selection as champions with the casual confidence of someone who has never once considered being told no. Champions of what, exactly, remains frustratingly unspecified, delivered in tones that suggest the deity finds the question itself slightly beneath them. What is specified, repeatedly and with obvious relish, is that the deity intends to watch, and expects the two of you to make the watching worthwhile — starting, apparently, immediately, judging by the faint but unmistakable sense of an audience that's settled over everything since the voice first spoke, watching, the two of you increasingly suspect, from considerably closer than the sky.""",

    """The support group meets weekly in a room that smells faintly of old coffee, a dozen people quietly comparing notes on abilities the outside world would call impossible or dangerous or both. It's usually a calm hour, mostly tea and cautious small talk between people who understand exactly why the small talk stays cautious. Today a new face walks in mid-session, says almost nothing, and manages within minutes to make every other person in the room — people who are, by definition, hard to frighten — visibly, unanimously afraid, without so much as raising their voice, and the group's usual moderator has quietly moved to stand nearest the door.""",

    """The map was cut in half generations ago by two relatives whose feud outlived them both, each half inherited by descendants who've never met and, according to family lore, were never supposed to. You're holding one half. The other, you've just learned, belongs to a distant relative you didn't know existed until a lawyer's letter arrived this week, along with a very pointed suggestion that the treasure the map points to is worth considerably more than either half alone — and that at least one other interested party has already worked that same math, started looking, and by the lawyer's uneasy tone, is not the sort of party either of you wants finding it first.""",

    """The cease-fire was meant to last one afternoon, long enough for both sides to negotiate terms across a folding table in a tent that smells like mud and gun oil. The negotiation stalled within the hour, both delegations retreating to opposite corners to argue among themselves. What didn't stall was the conversation that kept happening anyway, once the official talking points ran out — quieter, more honest, and considerably more dangerous to either of your reputations than the treaty itself, conducted in the narrow strip of tent where neither delegation could quite overhear, and where someone, eventually, is going to have to walk back out and pretend none of it happened.""",

    """The train hasn't stopped in longer than either of you can account for, and the destination board keeps changing to places neither of you has heard of, in a script that shifts alphabets between glances. The other passengers change too, subtly, between cars — different faces than the ones who boarded, though nobody else on the train seems to find that worth mentioning, chatting pleasantly as if the scenery outside hasn't stopped resembling anywhere either of you has ever traveled. You've noticed. You're fairly sure, now, that you're not imagining it, and that saying so out loud might not be entirely safe.""",

    """Midnight at the crossroads was supposed to be superstition, a story told to keep children from wandering after dark, right up until the figure actually appeared, offering each of you something specific and exactly tailored to what you privately want most, in a voice pleasant enough to make the offer feel almost reasonable. The catch, delivered almost as an afterthought once you've both leaned in to listen, is that the deal only completes if you both agree to take it — together, or not at all, a condition the figure seems to find quietly, deeply amusing, watching to see which of you speaks first.""",

    """The invasion doesn't come from across a border; it comes from somewhere considerably stranger, tearing open in the sky above a field where the two of you happen to be the only witnesses close enough to see clearly what's coming through — shapes that don't move like anything either of you recognizes, against a light that hurts to look at directly. No one else believes you yet, and every minute spent convincing someone is a minute the tear in the sky spends getting wider. That window won't stay open long, and neither, you're increasingly certain, will the one above the field.""",

    """Twelve hours in a stalled elevator is a long time to sit in silence with a stranger, and somewhere around hour six the silence broke into conversation, and somewhere around hour ten the conversation broke into honesty neither of you had planned on offering a stranger, of all people, in a stuck elevator, of all places, with the emergency phone dead and the lights running on backup power that's audibly starting to flicker. The doors will open eventually, probably. Neither of you is entirely sure what happens to this particular version of honesty once they do, or whether either of you will want to take any of it back once you're standing in the lobby.""",

    """The door wasn't there yesterday — you're both certain of that, having walked this same hallway dozens of times without it — and it's built into a wall that, by any reasonable measure, shouldn't have room for a door at all, given what's on the other side of that wall according to every floor plan either of you has ever seen. It's unlocked. Whatever's on the other side is close enough that you can feel a faint draft carrying air that smells like nowhere either of you has ever been, and the handle, when touched, is faintly, unmistakably warm, like it's been waiting for exactly this hand to finally reach for it.""",
]
_GOALS = [
    """Find the truth about their mysterious origins and the power sleeping within them. Every clue leads to another dead end, another guardian sworn to silence, another fragment of a story that only makes sense once three or four other fragments are found alongside it. They've stopped expecting a simple answer, and have started treating the search itself as a kind of discipline rather than a problem with a tidy solution waiting at the end of it. What drives them now isn't curiosity so much as the growing certainty that the power inside them won't stay dormant forever, and that understanding it before it wakes on its own terms might be the only choice that leaves them any say in what happens next, rather than simply reacting to it once it's already too late to prepare, and far too late to choose a gentler outcome.""",

    """Become the strongest {profession} in the realm and rewrite the rules of their art. Every master who came before built a tradition out of what worked in their own era, and every one of those traditions has calcified into dogma that no longer serves anyone but the people who benefit from things staying exactly as they are. They intend to prove, through results rather than argument, that the old rules were never sacred — just convenient for whoever wrote them — and that the art has room to grow into something better than what it inherited, whether the old masters approve of the growing or not. It has cost them allies who preferred the comfortable version of the tradition, and they've decided, after some real grief over the losses, that the cost was worth paying.""",

    """Avenge a loved one who was taken too soon by forces they're only beginning to understand. The grief hasn't faded so much as hardened into something with a purpose, a compass that points, however imperfectly, toward whoever gave the order and whoever carried it out, one careful lead at a time. They know vengeance won't bring anyone back, and they've stopped pretending otherwise to the people who ask them to let it go. They've decided that doesn't actually matter — that some debts get paid regardless of whether payment fixes anything, and that leaving this one unpaid would be its own kind of betrayal, one final failure added to a loss they already can't undo, and won't spend the rest of their life pretending they've made peace with.""",

    """Protect the one person who matters most to them, no matter the cost. Everything else — reputation, comfort, even their own safety — has become negotiable in a way it never used to be, weighed constantly and without much hesitation against the one thing they've decided isn't up for negotiation at all. They don't talk about it often, since saying it aloud makes the fear underneath it too real to ignore, but every decision they make now runs, eventually, through that single unbending priority, and they've stopped apologizing to anyone who finds that inconvenient. People who knew them before this priority took hold sometimes say they've changed. They have. They'd do it again exactly the same way.""",

    """Discover the cure for a deadly curse that threatens to consume them completely. The physicians ran out of ideas months ago; the priests offered comfort instead of solutions, which helped for approximately one bad night and stopped helping after that. What's left is a slow, methodical search through increasingly obscure sources — forbidden texts, half-mad hermits, rumors that turn out to be nothing more often than not — driven by a deadline that gets a little more real every time the curse's symptoms progress another visible degree. They've started keeping a private log of what's failed so far, less out of hope than out of the stubborn belief that ruling things out is still, technically, progress worth recording.""",

    """Build a home and find lasting peace after a lifetime of wandering and war. The idea used to feel embarrassingly small compared to the scale of everything they've survived, but somewhere along the way it stopped feeling small and started feeling like the only ambition that ever actually mattered, quietly outlasting every grander goal they used to chase instead. They're not entirely sure they know how to want something this quiet and stay still long enough to have it, but they're trying to learn, one deliberately unremarkable day at a time, treating boredom itself as a kind of victory they never expected to earn and are, some days, still slightly suspicious of trusting.""",

    """Master the ancient arts of their ancestors and pass them to the next generation before the last of the old teachers are gone. The tradition is fading faster than new students are arriving to learn it, and every year without a properly trained successor is a year closer to losing knowledge that took centuries to accumulate and cannot be reconstructed once it's actually gone. They've made peace with the fact that mastery alone won't be enough — the real work is in making the art something worth learning for people who've never been taught to value what's old, which means teaching persuasion nearly as often as they teach the actual craft, and getting better at both with every reluctant student who eventually comes around.""",

    """Unite the fractured factions under one banner before the darkness arrives, whatever coalition that ends up requiring. Diplomacy has failed more often than it's succeeded, old grudges keep resurfacing at exactly the wrong moments, and at least two factions would rather lose to the coming darkness than win alongside a rival they hate more than they fear the threat. None of that has convinced them to stop trying. They've simply gotten better at reading which arguments actually land, more patient about how many times they'll need to make them, and more willing to accept an ugly, temporary alliance over no alliance at all, on the theory that survival doesn't require anyone to actually like each other.""",

    """Find true love after years of loneliness, betrayal, and building walls around their heart that were, at the time, entirely reasonable to build. They know, intellectually, that the walls were justified given what put them there, and that tearing them down invites exactly the kind of risk that built them in the first place. They're trying anyway, slowly, in small deliberate acts of trust extended to people who haven't yet given them a reason not to — testing, every time, whether this particular attempt will be the one that finally holds, and trying not to flinch too visibly when it feels like it might not, because flinching, they've learned, tends to become its own kind of self-fulfilling prophecy.""",

    """Uncover and destroy a conspiracy that threatens to reshape the world in shadow, long before anyone else believes it's real enough to take seriously. Every piece of evidence they gather points to people with more power and better cover than the last, and the conspiracy's actual scope keeps expanding the closer they look — never smaller than they feared, always larger than they hoped it would turn out to be. They keep pulling the thread anyway, past the point of easy retreat, because stopping now would mean living the rest of their life knowing exactly how deep the rot goes and choosing to walk away from it rather than at least trying to cut it out while there's still time to matter.""",

    """Earn enough gold to buy freedom for their family still trapped in servitude, however long the arithmetic ends up taking. The math is brutal and unforgiving — a fixed price, a slow trickle of coin, and moneylenders whose interest rates are practically designed to keep debts like this one from ever actually closing no matter how diligently they're paid down. They take every job the math allows, however dangerous, and refuse every shortcut that would put the money at risk of vanishing before it reaches the people it's meant for, because a fast dishonest fortune is worth exactly nothing if it never actually arrives where it's needed, and they've watched that exact mistake ruin other families before theirs.""",

    """Prove themselves worthy of a legendary title that has gone unclaimed for centuries, without a clear checklist telling them how. The title's requirements are famously vague and famously strict at the same time, interpreted differently by every scholar who's studied them, which means there's no reliable path to follow — only a growing collection of deeds that might or might not eventually add up to enough by whatever standard actually judges these things. They keep doing the work regardless of whether anyone's watching to confirm it counts, on the theory that the title, if it means anything at all, should recognize itself when it's finally, unmistakably earned, and not a moment before that.""",

    """Break free from the chains of their past and become someone entirely new, even if the process takes considerably longer than they'd hoped. The old self keeps resurfacing in small, unwelcome ways — a familiar instinct in a dangerous moment, a name that still gets a reaction from strangers who shouldn't recognize it — and every relapse feels like proof that reinvention might be a story they're telling themselves rather than something actually achievable. They keep at it regardless, on the theory that becoming someone new was always going to be a practice, not a single completed transformation, and that the relapses are part of the practice rather than proof it's failing, however discouraging they feel in the moment they happen.""",

    """Find the legendary artifact before it falls into the wrong hands, whoever those hands ultimately turn out to belong to. Every lead they chase seems to be one step behind at least one other party with considerably worse intentions for what the artifact could do once found, and the gap never seems to close by more than a little at a time. The search has stopped being about the artifact's power for its own sake and become almost entirely defensive — not wanting it themselves so much as refusing to let it end up somewhere it absolutely shouldn't, even if that means carrying a burden they never actually asked for once they finally do catch up, and can't simply walk away from once it's in their hands.""",

    """Create something that will outlast them — a legacy that echoes through the ages, in whatever form that ends up taking. They're not entirely sure yet what shape it will take, and the not-knowing bothers them more than it probably should for someone who still has plenty of time left to figure it out and hasn't actually run out of chances yet. What's certain is the shape of the fear underneath the ambition: that without something deliberate left behind, they'll simply be forgotten the way most people eventually are, and that possibility has started to feel unacceptable enough to reorganize a fair amount of their life around avoiding it, sometimes at the expense of things that probably deserved more attention.""",

    """Understand the visions that plague their dreams and the entity that sends them, before the visions start demanding more than sleep. The visions never repeat exactly, but a pattern is slowly emerging underneath the chaos — recurring symbols, a voice that seems to be trying to communicate rather than simply torment, fragments that feel less like nightmares and more like a message sent by someone who hasn't yet found a clearer way to say it. Sleep has stopped being restful. It's become research, and they've started taking notes every morning before the details have a chance to fade, building a growing private catalogue that's starting, finally, to look less like noise and more like a language.""",

    """Find a way home, wherever home is, through whatever barriers stand in the way, no matter how long the journey ends up taking. The barriers keep changing shape — sometimes literal distance, sometimes politics, sometimes something considerably stranger that no map or ship or spell has managed to solve yet — but the destination hasn't wavered even once through any of it. They've learned to treat every setback as a detour rather than a dead end, mostly because the alternative, accepting that home might genuinely be unreachable, isn't something they're willing to consider yet, and may never be willing to consider, whatever the barriers eventually turn out to demand of them.""",

    """Redeem themselves for a terrible mistake that cost innocent lives, in whatever way redemption for something like that can actually work. No amount of good deeds since has fully balanced the ledger in their own mind, and they've stopped expecting it ever will — the goal has quietly shifted from erasing the guilt to simply making sure it drives something useful instead of something paralyzing. Every life they help now is, in some private accounting they rarely mention out loud, a small partial payment toward a debt they know can never actually be settled in full, no matter how long they keep making payments, or how much good eventually accumulates on the other side of the ledger.""",

    """Discover who is manipulating events from the shadows and why they chose this particular moment to finally start acting. The pattern is too consistent to be coincidence — the same subtle pressure applied across unrelated events, the same careful fingerprints left just visible enough to notice but never quite enough to prove in front of anyone who'd actually act on the proof. They've started keeping a private map of connections that most people would dismiss as paranoia, and every new piece that fits only sharpens the growing certainty that they're being watched at least as closely as they're watching, which is not, they've come to realize, a comfortable thing to be certain of.""",

    """Save the world, even though the world has never done anything for them and has mostly gone out of its way not to. The irony isn't lost on them, and neither is the fact that most of what they've received from the world has been indifference at best and active cruelty more often than they'd like to admit out loud to anyone who asks why they still bother. They're doing it anyway, not out of gratitude the world hasn't earned, but out of a stubborn, private conviction that the people who might still deserve saving are worth the effort even if the world at large hasn't been, and that the distinction matters more to them than it probably should to anyone with better reasons to walk away.""",

    """Master the {profession} traditions of a heritage they were raised apart from and finally claim it fully as their own, on their own terms. Years spent on the outside looking in taught them how to notice details that lifelong practitioners take for granted, and they've started to suspect that outsider's perspective might actually be an advantage rather than the deficiency everyone assumed it was when they first arrived. What they want now isn't just competence — it's the moment, whenever it arrives, when no one who once questioned their belonging can credibly question it again, and they've stopped needing that moment to arrive quickly, since rushing it would only give the doubters another excuse.""",

    """Master a martial discipline well enough that no one ever again mistakes their calm for weakness, having once nearly paid for that mistake with someone else's life. The training is slow and unglamorous, mostly repetition, mostly failure, mostly small incremental corrections that don't feel like progress until months have passed and the improvement is suddenly, undeniably obvious. They train alone more often than with a teacher now, having outpaced most of the instructors willing to work with someone this driven. What they're chasing isn't really strength for its own sake — it's the specific certainty that the next time it matters, hesitation won't be the thing that costs someone everything.""",

    """Track down the sibling they never knew existed before it's too late for the discovery to matter to either of them. Every lead is decades cold and every witness who might remember anything useful has scattered, died, or simply forgotten details that seemed unimportant at the time they happened. They keep the search going in whatever hours the rest of their life leaves free, treating each small confirmed fact — a name, a town, a date — as proof the thread hasn't actually gone as cold as it looks, even on the weeks when nothing new turns up at all and the search feels more like faith than investigation.""",

    """Restore honor to a family name that one relative's crimes dragged through the mud long before they were old enough to have any say in the matter. Most people they meet still recognize the name and react accordingly, and explaining the full context takes longer than most conversations allow, so more often than not they simply let the assumption stand and let their actions argue the case instead of their words. It's slow work, measured in small shifted opinions rather than any single dramatic vindication. They've decided slow is acceptable, as long as the direction stays consistently forward, and as long as they don't start resenting the relative more than the situation, honestly, already calls for.""",

    """Learn to control a power that terrifies even the people who love them most, before the lack of control costs them someone they can't afford to lose. Every lesson so far has come at a cost — a scorched room, a frightened friend, a near-miss that could easily have gone very differently than it did — and the fear of hurting someone they care about has become a more effective teacher than any deliberate training ever managed to be. They keep practicing anyway, carefully, because the alternative to learning control is simply waiting for the next accident to be worse than the last one, and that alternative has stopped being acceptable to them in any form.""",

    """Expose the truth behind a historical atrocity that official records have quietly erased, one verified fact at a time. The erasure wasn't accidental — someone with real resources went to considerable trouble to make sure this particular history stopped being taught, stopped being discussed, and eventually stopped being remembered by anyone who wasn't personally there to witness it firsthand. They've made it a personal mission to undo that erasure fact by fact, aware that whoever did the erasing in the first place is unlikely to welcome the reversal, and increasingly certain, from the resistance they've already met, that some of those people are still both powerful and very much alive.""",

    """Win back the trust of a community that cast them out for something they didn't do, without the benefit of ever getting a fair hearing. Explaining the truth hasn't worked; the accusation traveled faster and further than any correction ever could, and by the time the facts caught up the story had already hardened into common knowledge. What's working, slowly, is simply staying — showing up, helping when help is needed, refusing to give the community the easy satisfaction of confirming they were right to send someone away, until the pattern of consistent decency becomes harder to ignore than the old rumor, even for the people who were loudest in spreading it in the first place.""",

    """Reunite a scattered found-family torn apart by circumstances beyond anyone's control, member by difficult member. Some want to be found; at least one, as far as they can tell, is deliberately staying hidden, and they're still working out how to honor that particular choice without simply giving up on the search altogether out of respect for it. Every reunion so far has been worth the difficulty of getting there, which is the only real evidence they have that the ones still missing will be worth it too — evidence they're choosing to trust more than the mounting difficulty of each search would otherwise justify trusting.""",

    """Build something lasting for a community that has never had anything built to last, and has good reason to be suspicious of anyone who promises otherwise. Every previous attempt by outsiders came with strings attached, benefits that flowed mostly one direction, and promises that quietly evaporated once the outsiders got what they actually wanted from the arrangement. They're trying to do it differently — slower, with more genuine consultation than efficiency would normally allow for — and trying not to mind how long it's taking people to believe this attempt might actually be different, since the community's skepticism, honestly, was earned fairly by everyone who came through here before them.""",

    """Track and stop a plague of magical origin before it reaches the capital and the scale of the problem becomes unmanageable. The disease moves faster than any cure can be properly developed, and every town it passes through offers a slightly different mutation to study, which is useful for research and devastating for everyone actually living through it in real time. They've stopped sleeping properly since the outbreak began, treating rest as a luxury the timeline doesn't currently allow for, and pushing that math further than is probably wise, on the calculation that a tired healer working is still meaningfully better than no healer working at all.""",

    """Earn a place among {profession} legends through deeds rather than born privilege, the hard way, one undeniable result at a time. Everyone with the right bloodline gets the benefit of the doubt from the moment they walk into a room; they've had to earn every ounce of that same benefit through results that speak louder than any pedigree ever could on its own. It's exhausting, some days, watching people with a fraction of the skill get a fraction of the scrutiny they routinely face. They've decided the extra scrutiny, unfair as it plainly is, has at least made them sharper at the work than most of the people who never had to face it.""",

    """Break a generational curse before it claims them the way it claimed everyone before them in their line, without exception so far. The pattern is well documented and grimly consistent — same age, same symptoms, same ending — which gives them a deadline more precise and more frightening than most people ever have to face directly in their lives. They're chasing every lead that predecessors before them either missed entirely or simply ran out of time to follow properly, hoping the difference this time is simply more time to work with, and refusing to accept the pattern as inevitable just because it's held true, so far, for every single generation before this one.""",

    """Reclaim ancestral land taken by conquest generations before they were even born to have a say in losing it. The current occupants have their own generations of history layered onto that same ground now, complicating a claim that once felt morally simple into something considerably messier the longer they actually spend standing on it. They're still committed to reclaiming what was taken from their family. They're less certain than they used to be about what reclaiming should actually look like in practice, once the people currently living there stop being an abstraction in an old grievance and start being neighbors they've had real, complicated conversations with.""",

    """Prove that a prophecy naming them for disaster doesn't have to become destiny just because everyone around them insists it will. Everyone who's heard the prophecy treats their every choice as either confirmation or delay of an outcome they consider basically inevitable, which makes even ordinary decisions feel weighted in ways they resent more with each passing year of scrutiny. They keep choosing differently than the prophecy expects anyway, partly from genuine conviction that fate isn't fixed, and partly, they'll privately admit, out of pure stubbornness at being told who they're supposed to become by people who've never once asked them what they actually wanted to be instead.""",

    """Track down and confront the mentor who abandoned them mid-training without a word of explanation, however long it takes to find them. The abandonment left real gaps in what they know, gaps that have caused real, sometimes dangerous problems in the years since, and no amount of dedicated self-teaching has fully managed to close them. They want answers more than they want an apology at this point, though they suspect, if they're honest with themselves, that finding the mentor might deliver neither one — and they've decided to go looking anyway rather than keep wondering, for another year, what the real reason for leaving actually was.""",

    """Build a sanctuary for people like them who have nowhere else safe left to go, brick by literal or figurative brick. They know exactly what it felt like to need a place like that and not have one when it mattered most, and that memory has hardened into a very specific, very stubborn commitment to make sure fewer people after them have to learn the same hard lesson the way they did. Funding is scarce, suspicion from wary neighbors is common, and they've decided both problems are simply part of the ongoing work rather than reasons to stop, since the only real alternative on offer is leaving the work undone entirely.""",

    """Master a forbidden art well enough to use it safely, rather than let it master them the way it has consumed everyone else who's tried before. Every known practitioner before them either burned out, lost themselves entirely, or simply disappeared partway through the learning process, and the absence of any surviving teachers means they're working mostly from theory and their own increasingly careful trial and error. The risk is real and they know it better than anyone could tell them. They've decided the art is worth the risk anyway, for reasons they haven't fully explained even to themselves yet, and may not fully understand until they're much further into it than they currently are.""",

    """Track down the source of a corruption slowly spreading through their homeland's magic before it reaches somewhere it truly can't be undone. The corruption moves in ways that don't match any documented precedent, resistant to every cleansing ritual tried against it so far, and the scholars they've consulted keep offering theories that contradict each other more than they actually agree on anything useful. They're chasing the source personally now, past the point where sending reports up a chain of command felt like it was actually accomplishing anything at all, convinced that whatever's causing this won't politely wait for a committee to reach consensus about how to respond properly.""",

    """Earn enough standing to finally challenge the corrupt official who ruined their family's fortune and walked away from it entirely unpunished. Direct confrontation would end badly given the current, considerable gap in power between them, so the plan has become slower and more patient instead: build influence, gather allies, accumulate leverage, until the day arrives when the confrontation is actually winnable rather than merely emotionally satisfying to attempt. They think about that day often, more than they'd probably admit if asked directly. They're disciplined enough, so far, not to move before it actually arrives, even on the days when patience feels like its own particular kind of surrender.""",

    """Find a permanent cure for a shapeshifting curse that makes it dangerous to trust their own reflection on any given day. The curse triggers unpredictably, strongest under stress, which means the very situations that most call for a clear and steady head are exactly the ones most likely to cost them control of their own body entirely. Every potential cure they've tried has helped a little and fixed nothing completely, and they've learned, slowly and reluctantly, to treat incremental progress as real progress rather than a discouraging reminder of how far there still is left to go, because the alternative to that particular reframing is simply giving up on the search entirely.""",

    """Restore a destroyed order of {profession}s to something resembling its former purpose, even working almost entirely from fragments. Most of the original knowledge died with the people who held it when the order fell, and rebuilding from what's left means every reconstructed tradition is part historical record and part educated, careful guess. They've made peace with the guessing, mostly, on the theory that an imperfect revival still honors the original order's purpose better than letting it disappear from the world completely and permanently. Future generations, they've decided, can correct their mistakes later, as long as there's something left standing worth the trouble of correcting.""",

    """Track down whoever is impersonating them to commit crimes in their name, before the impersonation costs them everything they've actually built. The impostor is good — good enough that several people who should really know better have vouched for sightings that couldn't possibly have been real given where they actually were at the time. Every crime committed under their name makes clearing their genuine reputation harder than it was the last time, compounding faster than they can keep up with through denial alone. They've started keeping a careful, dated account of their true whereabouts, less out of paranoia than simple necessity, aware the account may eventually need to hold up in front of someone who isn't naturally inclined to believe them.""",

    """Earn a second chance from a guild that expelled them over a misunderstanding years ago that was never properly investigated at the time. The guild's official records still show the old, incomplete version of events, and every attempt to formally appeal that record has been quietly buried by someone with a clear interest in keeping it exactly that way. They've stopped waiting for the appeal process to work in their favor and started rebuilding a reputation from entirely outside the guild's structure instead, hoping that enough outside success eventually makes the old, incomplete records simply irrelevant, whether or not the guild itself ever formally admits it got the original ruling wrong.""",

    """Discover why their bloodline seems to attract catastrophe wherever it settles, generation after documented generation. The pattern goes back further than family records reliably cover, but far enough back regardless that it's clearly not simple bad luck repeating itself by pure coincidence across that many years. They're documenting every incident they can still verify, looking for the common thread underneath generations of accumulated disaster, half hoping to find an actual curse they can finally break through some concrete ritual, and half dreading the real possibility that the answer turns out to be something considerably harder to fix than any single ritual could ever manage to undo.""",

    """Track down a stolen family heirloom rumored to hold considerably more than sentimental value to whoever currently possesses it. The theft happened before they were even born, passed down as family legend more than clearly verified fact over the years, but recent evidence suggests the heirloom genuinely still exists, and recent rumors suggest it's changed dangerous hands more than once since the original theft occurred. They're chasing a trail that's decades cold at this point, treating every scrap of fresh confirmation as proof the search isn't as hopeless as it sometimes feels on the harder days, and refusing to let one more generation pass without at least trying to finish what was started.""",

    """Prove wrong every single person who once said they'd never amount to anything worth mentioning. The list of doubters is longer than they'd like to admit even now, and a surprising number of them were people whose good opinion, once, actually mattered a great deal more to them than they were ever willing to say out loud at the time it counted. They've mostly stopped needing that good opinion the way they used to need it. What's left instead is a quieter, steadier determination to keep succeeding regardless of whether any of those old doubters are even still around watching, or still alive to notice how wrong they turned out to be.""",

    """Build a bridge, literal or otherwise, between two peoples who have spent generations refusing to properly understand each other at all. Every attempt at reconciliation before theirs has collapsed under the accumulated weight of old grievances that neither side is willing to set down first, out of fear of looking weak to their own people. They keep trying anyway, treating each small successful exchange — a shared meal, a joint project, an unlikely friendship that technically shouldn't exist by the old unwritten rules — as proof that the bridge is genuinely possible, even if neither side is quite ready yet to admit that possibility out loud in front of their own communities.""",

    """Track down a cure for a loved one's affliction before that affliction becomes fully, medically irreversible. Every specialist consulted so far offers a slightly different diagnosis and a correspondingly different recommended treatment, none of which have actually worked yet, and the clock the affliction is running on doesn't pause politely for further careful research to catch up. They're chasing every available lead simultaneously now, unwilling to bet everything on any single theory when time is this genuinely short and the stakes involved are this personal to them, even when that approach means exhausting money and favors considerably faster than either can reasonably be replaced.""",

    """Master enough of the old languages to finally read a family journal that's been passed down illegibly for three full generations already. Every translator consulted so far has managed only scattered fragments, disagreeing sharply with each other about even the most basic meaning, which has left the journal's real content a standing family mystery for longer than most of the family has actually been willing to admit still bothers them privately. They've decided to learn the language themselves rather than keep trusting translations that never fully agree with one another, even if it ends up taking years longer than simply hiring the right qualified expert would have taken from the start.""",

    """Track down every surviving student of a teacher who was murdered before finishing their training, and finish, together, what none of them could ever complete alone. Each surviving student carries a different fragment of the original curriculum, taught to them in a different order, remembered now with different gaps depending on how long ago they studied. Reassembling the whole picture means finding people who scattered deliberately after the murder, out of grief or fear or both, and convincing at least some of them to trust a near-stranger with a loss they've each spent years carefully trying not to revisit at all, let alone with someone they've only just met.""",

    """Win a formal pardon for a crime they genuinely did commit, not by denying it ever happened but by proving, deed after deliberate deed, that the person who committed it no longer exists in any way that meaningfully matters now. The old charge stays on the official record regardless of how much demonstrable good follows it afterward, a permanent asterisk that quietly colors every fresh start they attempt to build for themselves. They've stopped expecting the asterisk to disappear entirely from anyone's memory or any official ledger. What they're actually working toward, patiently, is the day it finally stops being the very first thing anyone mentions when they hear their name spoken aloud.""",
]

def random_backstory(race="", profession=""):
    bs = random.choice(_BACKSTORIES)
    return bs.replace("{race}", race or "unknown").replace("{profession}", profession or "adventurer")

def random_scenario():
    return random.choice(_SCENARIOS)

def random_goals(profession=""):
    g = random.choice(_GOALS)
    return g.replace("{profession}", profession or "warrior")

